<header class="page-header"><div><p class="eyebrow">Lead Finder</p><h1>Ideal customer profile</h1><p>Tell the agent what a good lead looks like.</p></div></header><form method="post" action="<?= $escape($actionUrl) ?>"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="version" value="<?= $escape($profile['version']) ?>"><label>Profile description<input name="description" value="<?= $escape($profile['description']) ?>" maxlength="500"></label><div class="field-grid"><label>Required signals<textarea name="required_any" rows="7"><?php foreach($profile['required_any'] as $value):?><?= $escape($value) ?>
